CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(64) PRIMARY KEY, applied_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id VARCHAR(64) PRIMARY KEY, title VARCHAR(255) NOT NULL, summary TEXT, current_version_id VARCHAR(64), created_by VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS document_versions (id VARCHAR(64) PRIMARY KEY, document_id VARCHAR(64) NOT NULL, version_no INTEGER NOT NULL, content TEXT NOT NULL, content_hash VARCHAR(64) NOT NULL, parent_version_id VARCHAR(64), rollback_from_version_id VARCHAR(64), created_at TIMESTAMP NOT NULL, UNIQUE(document_id, version_no));
CREATE TABLE IF NOT EXISTS version_paragraphs (id VARCHAR(64) PRIMARY KEY, version_id VARCHAR(64) NOT NULL, position INTEGER NOT NULL, content TEXT NOT NULL, content_hash VARCHAR(64) NOT NULL, UNIQUE(version_id, position));
CREATE TABLE IF NOT EXISTS comparison_jobs (id VARCHAR(64) PRIMARY KEY, base_version_id VARCHAR(64) NOT NULL, target_version_id VARCHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, error_message TEXT, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id VARCHAR(64) PRIMARY KEY, document_id VARCHAR(64) NOT NULL, version_id VARCHAR(64) NOT NULL, paragraph_id VARCHAR(64), content TEXT NOT NULL, author_id VARCHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id VARCHAR(64) PRIMARY KEY, actor_id VARCHAR(64) NOT NULL, action VARCHAR(64) NOT NULL, entity_type VARCHAR(64) NOT NULL, entity_id VARCHAR(64) NOT NULL, trace_id VARCHAR(64) NOT NULL, detail_json TEXT, created_at TIMESTAMP NOT NULL);
